=== FILE: axi4_lite_regs.v ===
`timescale 1ns/1ps
`default_nettype none

// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements microarchitecture.md: holding registers for
// AW and W, READY computed from state only, one outstanding transaction per
// direction, 1-cycle response latency, SLVERR for unmapped (misaligned)
// addresses. Reset is synchronous, active low.
module axi4_lite_regs #(
    parameter ADDR_WIDTH = 4,
    parameter DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,
    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,
    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

  localparam STRB_WIDTH = DATA_WIDTH / 8;
  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  // An address is mapped when word aligned and inside the 16-byte window.
  function is_mapped;
    input [ADDR_WIDTH-1:0] a;
    begin
      is_mapped = (a[1:0] == 2'b00) && ((a >> 4) == {ADDR_WIDTH{1'b0}});
    end
  endfunction

  // ---------------------------------------------------------------- state
  reg                  aw_held_q;
  reg                  aw_held_d;
  reg                  w_held_q;
  reg                  w_held_d;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg [DATA_WIDTH-1:0] w_data_q;
  reg [STRB_WIDTH-1:0] w_strb_q;
  reg                  bvalid_q;
  reg                  bvalid_d;
  reg [1:0]            bresp_q;
  reg [1:0]            bresp_d;
  reg                  rvalid_q;
  reg                  rvalid_d;
  reg [1:0]            rresp_q;
  reg [1:0]            rresp_d;
  reg [DATA_WIDTH-1:0] rdata_q;
  reg [DATA_WIDTH-1:0] rdata_d;
  reg [DATA_WIDTH-1:0] reg0_q;
  reg [DATA_WIDTH-1:0] reg1_q;
  reg [DATA_WIDTH-1:0] reg2_q;
  reg [DATA_WIDTH-1:0] reg3_q;
  reg [DATA_WIDTH-1:0] reg0_d;
  reg [DATA_WIDTH-1:0] reg1_d;
  reg [DATA_WIDTH-1:0] reg2_d;
  reg [DATA_WIDTH-1:0] reg3_d;
  reg [DATA_WIDTH-1:0] rd_sel;

  // ------------------------------------------- READY from state only
  assign s_axil_awready = !aw_held_q && !bvalid_q;
  assign s_axil_wready  = !w_held_q  && !bvalid_q;
  assign s_axil_arready = !rvalid_q;

  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rresp   = rresp_q;
  assign s_axil_rdata   = rdata_q;

  wire aw_hs = s_axil_awvalid && s_axil_awready;
  wire w_hs  = s_axil_wvalid  && s_axil_wready;
  wire ar_hs = s_axil_arvalid && s_axil_arready;

  // ------------------------------------------------------- write path
  wire                  do_write  = (aw_held_q || aw_hs) && (w_held_q || w_hs);
  wire [ADDR_WIDTH-1:0] wr_addr   = aw_held_q ? aw_addr_q : s_axil_awaddr;
  wire [DATA_WIDTH-1:0] wr_data   = w_held_q  ? w_data_q  : s_axil_wdata;
  wire [STRB_WIDTH-1:0] wr_strb   = w_held_q  ? w_strb_q  : s_axil_wstrb;
  wire                  wr_mapped = is_mapped(wr_addr);
  wire [1:0]            wr_idx    = wr_addr[3:2];
  wire [DATA_WIDTH-1:0] wr_mask;

  genvar g;
  generate
    for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_wr_mask
      assign wr_mask[8*g +: 8] = {8{wr_strb[g]}};
    end
  endgenerate

  // Held flags: set when one half arrives alone, cleared when the pair fires.
  always @* begin
    aw_held_d = aw_held_q;
    w_held_d  = w_held_q;
    if (do_write) begin
      aw_held_d = 1'b0;
      w_held_d  = 1'b0;
    end else begin
      if (aw_hs) aw_held_d = 1'b1;
      if (w_hs)  w_held_d  = 1'b1;
    end
  end

  // Write response.
  always @* begin
    bvalid_d = bvalid_q;
    bresp_d  = bresp_q;
    if (do_write) begin
      bvalid_d = 1'b1;
      bresp_d  = wr_mapped ? RESP_OKAY : RESP_SLVERR;
    end else if (bvalid_q && s_axil_bready) begin
      bvalid_d = 1'b0;
    end
  end

  // Register file: merge enabled bytes into the addressed register.
  always @* begin
    reg0_d = reg0_q;
    reg1_d = reg1_q;
    reg2_d = reg2_q;
    reg3_d = reg3_q;
    if (do_write && wr_mapped) begin
      case (wr_idx)
        2'd0:    reg0_d = (reg0_q & ~wr_mask) | (wr_data & wr_mask);
        2'd1:    reg1_d = (reg1_q & ~wr_mask) | (wr_data & wr_mask);
        2'd2:    reg2_d = (reg2_q & ~wr_mask) | (wr_data & wr_mask);
        2'd3:    reg3_d = (reg3_q & ~wr_mask) | (wr_data & wr_mask);
        default: reg0_d = reg0_q;
      endcase
    end
  end

  // -------------------------------------------------------- read path
  wire ar_mapped = is_mapped(s_axil_araddr);

  always @* begin
    case (s_axil_araddr[3:2])
      2'd0:    rd_sel = reg0_q;
      2'd1:    rd_sel = reg1_q;
      2'd2:    rd_sel = reg2_q;
      2'd3:    rd_sel = reg3_q;
      default: rd_sel = {DATA_WIDTH{1'b0}};
    endcase
  end

  always @* begin
    rvalid_d = rvalid_q;
    rresp_d  = rresp_q;
    rdata_d  = rdata_q;
    if (ar_hs) begin
      rvalid_d = 1'b1;
      rresp_d  = ar_mapped ? RESP_OKAY : RESP_SLVERR;
      rdata_d  = ar_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
    end else if (rvalid_q && s_axil_rready) begin
      rvalid_d = 1'b0;
    end
  end

  // ------------------------------------------------- state registers
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      w_held_q  <= 1'b0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rresp_q   <= RESP_OKAY;
      rdata_q   <= {DATA_WIDTH{1'b0}};
      reg0_q    <= {DATA_WIDTH{1'b0}};
      reg1_q    <= {DATA_WIDTH{1'b0}};
      reg2_q    <= {DATA_WIDTH{1'b0}};
      reg3_q    <= {DATA_WIDTH{1'b0}};
    end else begin
      aw_held_q <= aw_held_d;
      w_held_q  <= w_held_d;
      bvalid_q  <= bvalid_d;
      bresp_q   <= bresp_d;
      rvalid_q  <= rvalid_d;
      rresp_q   <= rresp_d;
      rdata_q   <= rdata_d;
      reg0_q    <= reg0_d;
      reg1_q    <= reg1_d;
      reg2_q    <= reg2_d;
      reg3_q    <= reg3_d;
    end
  end

  // Holding registers: datapath only, guarded by the reset held flags.
  always @(posedge aclk) begin
    if (aw_hs) begin
      aw_addr_q <= s_axil_awaddr;
    end
    if (w_hs) begin
      w_data_q <= s_axil_wdata;
      w_strb_q <= s_axil_wstrb;
    end
  end

`ifdef FORMAL
  // Design-intent properties (not yet run: no .sby submitted with this task).
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  // Start in reset.
  always @(*) if (!f_past_valid) assume(!aresetn);

  // Manager: VALID low while in reset.
  always @(*) if (!aresetn) assume(!s_axil_awvalid && !s_axil_wvalid && !s_axil_arvalid);

  // Manager: VALID and payload hold until the handshake.
  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn) && aresetn) begin
      if ($past(s_axil_awvalid && !s_axil_awready))
        assume(s_axil_awvalid && $stable(s_axil_awaddr));
      if ($past(s_axil_wvalid && !s_axil_wready))
        assume(s_axil_wvalid && $stable(s_axil_wdata) && $stable(s_axil_wstrb));
      if ($past(s_axil_arvalid && !s_axil_arready))
        assume(s_axil_arvalid && $stable(s_axil_araddr));
    end
  end

  // Responses low after reset; half-accepted writes dropped.
  always @(posedge aclk) begin
    if (f_past_valid && !$past(aresetn)) begin
      assert(!s_axil_bvalid);
      assert(!s_axil_rvalid);
      assert(!aw_held_q && !w_held_q);
    end
  end

  // B and R hold, with a stable payload, until taken.
  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn)) begin
      if ($past(s_axil_bvalid && !s_axil_bready)) begin
        assert(s_axil_bvalid);
        assert($stable(s_axil_bresp));
      end
      if ($past(s_axil_rvalid && !s_axil_rready)) begin
        assert(s_axil_rvalid);
        assert($stable(s_axil_rresp));
        assert($stable(s_axil_rdata));
      end
    end
  end

  // A response follows exactly one accepted request, one cycle later,
  // with the code chosen by the address policy.
  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn)) begin
      if ($past(do_write)) begin
        assert(s_axil_bvalid);
        assert(s_axil_bresp == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR));
      end else if (!$past(bvalid_q)) begin
        assert(!s_axil_bvalid);
      end
      if ($past(ar_hs)) begin
        assert(s_axil_rvalid);
        assert(s_axil_rresp == ($past(ar_mapped) ? RESP_OKAY : RESP_SLVERR));
      end else if (!$past(rvalid_q)) begin
        assert(!s_axil_rvalid);
      end
    end
  end

  // State invariants: at most one write open; no response code 2'b01/2'b11.
  always @(*) begin
    assert(!(aw_held_q && w_held_q));
    if (bvalid_q) assert(!aw_held_q && !w_held_q);
    assert((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
    assert((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
    if (rvalid_q && (rresp_q == RESP_SLVERR)) assert(rdata_q == {DATA_WIDTH{1'b0}});
  end

  always @(posedge aclk) begin
    if (f_past_valid && aresetn) begin
      cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_OKAY));
      cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_SLVERR));
      cover(s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_OKAY));
      cover(aw_held_q);
      cover(w_held_q);
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: axi4_lite_regs_tb.v ===
`timescale 1ns/1ps
`default_nettype none

// Self-checking testbench for axi4_lite_regs. Inputs are driven at the
// falling edge; READY/VALID outputs depend only on state, so the handshake
// that will occur at the next rising edge is known when inputs are driven.

`define CHECK(cond, msg) \
  begin \
    if (cond) passed = passed + 1; \
    else begin \
      failed = failed + 1; \
      $error msg; \
    end \
  end

module axi4_lite_regs_tb;

  localparam [1:0] OKAY    = 2'b00;
  localparam [1:0] SLVERR  = 2'b10;
  localparam integer TIMEOUT = 40;

  reg         aclk;
  reg         aresetn;
  reg  [3:0]  awaddr;
  reg         awvalid;
  wire        awready;
  reg  [31:0] wdata;
  reg  [3:0]  wstrb;
  reg         wvalid;
  wire        wready;
  wire [1:0]  bresp;
  wire        bvalid;
  reg         bready;
  reg  [3:0]  araddr;
  reg         arvalid;
  wire        arready;
  wire [31:0] rdata;
  wire [1:0]  rresp;
  wire        rvalid;
  reg         rready;

  integer        passed;
  integer        failed;
  integer        got_nonce;
  integer        k;
  reg [8*64-1:0] nonce;
  reg [31:0]     model [0:3];

  axi4_lite_regs #(
      .ADDR_WIDTH(4),
      .DATA_WIDTH(32)
  ) dut (
      .aclk           (aclk),
      .aresetn        (aresetn),
      .s_axil_awaddr  (awaddr),
      .s_axil_awvalid (awvalid),
      .s_axil_awready (awready),
      .s_axil_wdata   (wdata),
      .s_axil_wstrb   (wstrb),
      .s_axil_wvalid  (wvalid),
      .s_axil_wready  (wready),
      .s_axil_bresp   (bresp),
      .s_axil_bvalid  (bvalid),
      .s_axil_bready  (bready),
      .s_axil_araddr  (araddr),
      .s_axil_arvalid (arvalid),
      .s_axil_arready (arready),
      .s_axil_rdata   (rdata),
      .s_axil_rresp   (rresp),
      .s_axil_rvalid  (rvalid),
      .s_axil_rready  (rready)
  );

  initial begin
    aclk = 1'b0;
    forever #5 aclk = ~aclk;
  end

  // Reference model -------------------------------------------------------
  function tb_mapped;
    input [3:0] a;
    begin
      tb_mapped = (a[1:0] == 2'b00);
    end
  endfunction

  function [31:0] tb_merge;
    input [31:0] old_v;
    input [31:0] new_v;
    input [3:0]  s;
    begin
      tb_merge = old_v;
      if (s[0]) tb_merge[7:0]   = new_v[7:0];
      if (s[1]) tb_merge[15:8]  = new_v[15:8];
      if (s[2]) tb_merge[23:16] = new_v[23:16];
      if (s[3]) tb_merge[31:24] = new_v[31:24];
    end
  endfunction

  // One write and/or one read, cycle by cycle. *_dly: cycles before VALID is
  // raised. b_stall/r_stall: cycles READY stays low after VALID is seen;
  // a negative stall raises READY before VALID.
  task automatic run_txn;
    input         wr_en;
    input [3:0]   t_awaddr;
    input [31:0]  t_wdata;
    input [3:0]   t_wstrb;
    input integer aw_dly;
    input integer w_dly;
    input integer b_stall;
    input         rd_en;
    input [3:0]   t_araddr;
    input integer ar_dly;
    input integer r_stall;
    integer    cyc;
    integer    wr_req_cyc;
    integer    b_first;
    integer    ar_req_cyc;
    integer    r_first;
    reg        aw_done;
    reg        w_done;
    reg        b_done;
    reg        ar_done;
    reg        r_done;
    reg        aw_hs;
    reg        w_hs;
    reg        b_hs;
    reg        ar_hs;
    reg        r_hs;
    reg [1:0]  exp_bresp;
    reg [1:0]  exp_rresp;
    reg [31:0] exp_rdata;
    reg [1:0]  held_bresp;
    reg [1:0]  held_rresp;
    reg [31:0] held_rdata;
    begin
      cyc        = 0;
      wr_req_cyc = -1;
      b_first    = -1;
      ar_req_cyc = -1;
      r_first    = -1;
      aw_done    = !wr_en;
      w_done     = !wr_en;
      b_done     = !wr_en;
      ar_done    = !rd_en;
      r_done     = !rd_en;
      exp_bresp  = OKAY;
      exp_rresp  = OKAY;
      exp_rdata  = 32'h0;
      held_bresp = OKAY;
      held_rresp = OKAY;
      held_rdata = 32'h0;
      while ((!b_done || !r_done) && (cyc < TIMEOUT)) begin
        @(negedge aclk);
        // ---- observe outputs (state from the last rising edge)
        if (cyc == 0) begin
          if (wr_en) begin
            `CHECK(awready && wready, ("write channel not ready at transaction start (t=%0t)", $time))
          end
          if (rd_en) begin
            `CHECK(arready, ("read channel not ready at transaction start (t=%0t)", $time))
          end
        end

        if (!wr_en || b_done) begin
          `CHECK(!bvalid, ("BVALID high with no write awaiting a response (t=%0t)", $time))
        end else if (bvalid) begin
          if (b_first < 0) begin
            b_first = cyc;
            `CHECK(wr_req_cyc >= 0, ("BVALID before both AW and W were accepted (t=%0t)", $time))
            `CHECK((cyc - wr_req_cyc >= 1) && (cyc - wr_req_cyc <= 2), ("write latency %0d outside 1..2 (t=%0t)", cyc - wr_req_cyc, $time))
            `CHECK(bresp == exp_bresp, ("BRESP %b for addr 0x%h, expected %b (t=%0t)", bresp, t_awaddr, exp_bresp, $time))
            held_bresp = bresp;
          end else begin
            `CHECK(bresp == held_bresp, ("BRESP changed while BREADY low (t=%0t)", $time))
          end
          `CHECK(!awready && !wready, ("AWREADY or WREADY high while a write response is pending (t=%0t)", $time))
        end else begin
          `CHECK(b_first < 0, ("BVALID dropped before it was taken (t=%0t)", $time))
          if ((wr_req_cyc >= 0) && (cyc - wr_req_cyc > 2)) begin
            failed = failed + 1;
            $error("no write response within 2 cycles of the request (t=%0t)", $time);
          end
        end

        if (!rd_en || r_done) begin
          `CHECK(!rvalid, ("RVALID high with no read awaiting data (t=%0t)", $time))
        end else if (rvalid) begin
          if (r_first < 0) begin
            r_first = cyc;
            `CHECK(ar_req_cyc >= 0, ("RVALID before AR was accepted (t=%0t)", $time))
            `CHECK((cyc - ar_req_cyc >= 1) && (cyc - ar_req_cyc <= 2), ("read latency %0d outside 1..2 (t=%0t)", cyc - ar_req_cyc, $time))
            `CHECK(rresp == exp_rresp, ("RRESP %b for addr 0x%h, expected %b (t=%0t)", rresp, t_araddr, exp_rresp, $time))
            `CHECK(rdata == exp_rdata, ("read of 0x%h returned %h, expected %h (t=%0t)", t_araddr, rdata, exp_rdata, $time))
            held_rresp = rresp;
            held_rdata = rdata;
          end else begin
            `CHECK((rresp == held_rresp) && (rdata == held_rdata), ("RDATA or RRESP changed while RREADY low (t=%0t)", $time))
          end
          `CHECK(!arready, ("ARREADY high while read data is pending (t=%0t)", $time))
        end else begin
          `CHECK(r_first < 0, ("RVALID dropped before it was taken (t=%0t)", $time))
          if ((ar_req_cyc >= 0) && (cyc - ar_req_cyc > 2)) begin
            failed = failed + 1;
            $error("no read response within 2 cycles of the request (t=%0t)", $time);
          end
        end

        // ---- drive inputs for the next rising edge
        awaddr  = t_awaddr;
        awvalid = wr_en && !aw_done && (cyc >= aw_dly);
        wdata   = t_wdata;
        wstrb   = t_wstrb;
        wvalid  = wr_en && !w_done && (cyc >= w_dly);
        bready  = wr_en && !b_done &&
                  ((b_stall < 0) || ((b_first >= 0) && (cyc - b_first >= b_stall)));
        araddr  = t_araddr;
        arvalid = rd_en && !ar_done && (cyc >= ar_dly);
        rready  = rd_en && !r_done &&
                  ((r_stall < 0) || ((r_first >= 0) && (cyc - r_first >= r_stall)));

        aw_hs = awvalid && awready;
        w_hs  = wvalid  && wready;
        b_hs  = bvalid  && bready;
        ar_hs = arvalid && arready;
        r_hs  = rvalid  && rready;

        @(posedge aclk);
        // ---- model the edge: a read sees register values before this edge's write
        if (ar_hs) begin
          ar_done    = 1'b1;
          ar_req_cyc = cyc;
          exp_rresp  = tb_mapped(t_araddr) ? OKAY : SLVERR;
          exp_rdata  = tb_mapped(t_araddr) ? model[t_araddr[3:2]] : 32'h0;
        end
        if (aw_hs) aw_done = 1'b1;
        if (w_hs)  w_done  = 1'b1;
        if (wr_en && (wr_req_cyc < 0) && aw_done && w_done) begin
          wr_req_cyc = cyc;
          exp_bresp  = tb_mapped(t_awaddr) ? OKAY : SLVERR;
          if (tb_mapped(t_awaddr))
            model[t_awaddr[3:2]] = tb_merge(model[t_awaddr[3:2]], t_wdata, t_wstrb);
        end
        if (b_hs) b_done = 1'b1;
        if (r_hs) r_done = 1'b1;
        cyc = cyc + 1;
      end
      if (!(b_done && r_done)) begin
        failed = failed + 1;
        $error("transaction timed out (wr=%b addr 0x%h, rd=%b addr 0x%h, t=%0t)", wr_en, t_awaddr, rd_en, t_araddr, $time);
      end
    end
  endtask

  task automatic wr;
    input [3:0]   a;
    input [31:0]  d;
    input [3:0]   s;
    input integer aw_dly;
    input integer w_dly;
    input integer b_stall;
    begin
      run_txn(1'b1, a, d, s, aw_dly, w_dly, b_stall, 1'b0, 4'h0, 0, 0);
    end
  endtask

  task automatic rd;
    input [3:0]   a;
    input integer ar_dly;
    input integer r_stall;
    begin
      run_txn(1'b0, 4'h0, 32'h0, 4'h0, 0, 0, 0, 1'b1, a, ar_dly, r_stall);
    end
  endtask

  task automatic read_all;
    begin
      rd(4'h0, 0, 0);
      rd(4'h4, 0, 1);
      rd(4'h8, 1, 0);
      rd(4'hC, 0, -1);
    end
  endtask

  task automatic idle;
    begin
      @(negedge aclk);
      awvalid = 1'b0;
      wvalid  = 1'b0;
      arvalid = 1'b0;
      bready  = 1'b0;
      rready  = 1'b0;
    end
  endtask

  task automatic apply_reset;
    input integer n;
    begin
      @(negedge aclk);
      aresetn = 1'b0;
      awvalid = 1'b0;
      wvalid  = 1'b0;
      arvalid = 1'b0;
      bready  = 1'b0;
      rready  = 1'b0;
      repeat (n) @(posedge aclk);
      @(negedge aclk);
      aresetn = 1'b1;
      for (k = 0; k < 4; k = k + 1) model[k] = 32'h0;
      `CHECK(!bvalid && !rvalid, ("BVALID or RVALID high after reset (t=%0t)", $time))
      `CHECK(awready && wready && arready, ("READY low after reset (t=%0t)", $time))
    end
  endtask

  // Test sequence ----------------------------------------------------------
  initial begin
    passed  = 0;
    failed  = 0;
    nonce   = {8*64{1'b0}};
    got_nonce = $value$plusargs("nirmaan_nonce=%s", nonce);
    if (got_nonce == 0) $display("note: no +nirmaan_nonce given");
    aresetn = 1'b0;
    awaddr  = 4'h0;
    awvalid = 1'b0;
    wdata   = 32'h0;
    wstrb   = 4'h0;
    wvalid  = 1'b0;
    bready  = 1'b0;
    araddr  = 4'h0;
    arvalid = 1'b0;
    rready  = 1'b0;
    for (k = 0; k < 4; k = k + 1) model[k] = 32'h0;

    apply_reset(3);

    // 1. Reset values.
    read_all;

    // 2. Write then read every register (AW and W together, BREADY early and late).
    wr(4'h0, 32'h1111_1111, 4'hF, 0, 0, 0);
    wr(4'h4, 32'h2222_2222, 4'hF, 0, 0, -1);
    wr(4'h8, 32'h3333_3333, 4'hF, 0, 0, 0);
    wr(4'hC, 32'h4444_4444, 4'hF, 0, 0, -1);
    read_all;

    // 3. AW/W ordering: AW first, W first, gaps, together after a delay.
    wr(4'h0, 32'hA0A0_0001, 4'hF, 0, 3, 0);
    wr(4'h4, 32'hA0A0_0002, 4'hF, 3, 0, 0);
    wr(4'h8, 32'hA0A0_0003, 4'hF, 1, 0, 0);
    wr(4'hC, 32'hA0A0_0004, 4'hF, 0, 1, -1);
    wr(4'h0, 32'hA0A0_0005, 4'hF, 2, 2, 0);
    read_all;

    // 4. Byte strobes.
    wr(4'h8, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
    wr(4'h8, 32'h1122_3344, 4'b0101, 0, 0, 0);
    `CHECK(model[2] == 32'hFF22_FF44, ("model mismatch for strobe 0101: %h", model[2]))
    rd(4'h8, 0, 0);
    wr(4'hC, 32'h0000_0000, 4'hF, 0, 0, 0);
    wr(4'hC, 32'hAAAA_AA11, 4'b0001, 0, 2, 0);
    wr(4'hC, 32'hAAAA_22AA, 4'b0010, 2, 0, 0);
    wr(4'hC, 32'hAA33_AAAA, 4'b0100, 0, 0, 1);
    wr(4'hC, 32'h44AA_AAAA, 4'b1000, 0, 0, 0);
    `CHECK(model[3] == 32'h4433_2211, ("model mismatch for single strobes: %h", model[3]))
    rd(4'hC, 0, 0);
    wr(4'hC, 32'hDEAD_BEEF, 4'b0000, 0, 0, 0);
    rd(4'hC, 0, 0);

    // 5. B and R backpressure.
    wr(4'h4, 32'hB0B0_0001, 4'hF, 0, 0, 5);
    wr(4'h4, 32'hB0B0_0002, 4'hF, 0, 2, 4);
    rd(4'h4, 0, 5);
    rd(4'h0, 2, 3);

    // 6. Back-to-back transactions.
    wr(4'h0, 32'h0102_0304, 4'hF, 0, 0, -1);
    wr(4'h4, 32'h0506_0708, 4'hF, 0, 0, -1);
    wr(4'h8, 32'h090A_0B0C, 4'hF, 0, 0, -1);
    wr(4'hC, 32'h0D0E_0F10, 4'hF, 0, 0, -1);
    rd(4'h0, 0, -1);
    rd(4'h4, 0, -1);
    rd(4'h8, 0, -1);
    rd(4'hC, 0, -1);

    // 7. SLVERR policy for unmapped (misaligned) addresses.
    wr(4'h5, 32'hBAD0_0005, 4'hF, 0, 0, 0);
    wr(4'hE, 32'hBAD0_000E, 4'hF, 1, 0, 2);
    wr(4'h3, 32'hBAD0_0003, 4'h0, 0, 0, 0);
    wr(4'h9, 32'hBAD0_0009, 4'b0011, 0, 2, 0);
    read_all;
    rd(4'h1, 0, 0);
    rd(4'h2, 0, 2);
    rd(4'hE, 1, 0);
    rd(4'hF, 0, 0);

    // 8. Reads and writes in flight together.
    run_txn(1'b1, 4'h8, 32'hC0DE_0008, 4'hF, 0, 0, 0, 1'b1, 4'h8, 0, 0);
    run_txn(1'b1, 4'h0, 32'hC0DE_0000, 4'hF, 0, 0, 3, 1'b1, 4'h4, 0, 2);
    run_txn(1'b1, 4'h4, 32'hC0DE_0004, 4'hF, 0, 2, 0, 1'b1, 4'h4, 4, 0);
    run_txn(1'b1, 4'hC, 32'hC0DE_000C, 4'hF, 2, 0, 2, 1'b1, 4'h0, 1, 3);
    run_txn(1'b1, 4'h5, 32'hC0DE_0005, 4'hF, 0, 0, 0, 1'b1, 4'hE, 0, 0);
    read_all;

    // 9a. Reset with an AW-only half write and a read response pending.
    wr(4'h4, 32'h7777_7777, 4'hF, 0, 0, 0);
    @(negedge aclk);
    awaddr  = 4'h0;
    awvalid = 1'b1;
    wvalid  = 1'b0;
    araddr  = 4'h4;
    arvalid = 1'b1;
    bready  = 1'b0;
    rready  = 1'b0;
    `CHECK(awready && arready, ("not ready before reset test (t=%0t)", $time))
    @(posedge aclk);
    @(negedge aclk);
    awvalid = 1'b0;
    arvalid = 1'b0;
    `CHECK(!awready && wready, ("AW not held after AW-only accept (t=%0t)", $time))
    `CHECK(rvalid && (rdata == model[1]) && (rresp == OKAY), ("read before reset wrong: %h (t=%0t)", rdata, $time))
    apply_reset(2);
    wr(4'hC, 32'h5A5A_5A5A, 4'hF, 3, 0, 0);
    read_all;

    // 9b. Reset with a write response pending.
    @(negedge aclk);
    awaddr  = 4'h8;
    wdata   = 32'h9999_9999;
    wstrb   = 4'hF;
    awvalid = 1'b1;
    wvalid  = 1'b1;
    bready  = 1'b0;
    @(posedge aclk);
    @(negedge aclk);
    awvalid = 1'b0;
    wvalid  = 1'b0;
    `CHECK(bvalid && (bresp == OKAY), ("BVALID not raised before reset (t=%0t)", $time))
    apply_reset(1);
    read_all;

    // 9c. Reset with a W-only half write.
    @(negedge aclk);
    wdata  = 32'h6666_6666;
    wstrb  = 4'hF;
    wvalid = 1'b1;
    @(posedge aclk);
    @(negedge aclk);
    wvalid = 1'b0;
    `CHECK(awready && !wready, ("W not held after W-only accept (t=%0t)", $time))
    apply_reset(1);
    wr(4'h0, 32'h1234_5678, 4'hF, 0, 3, 0);
    read_all;

    idle;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule

`default_nettype wire
